package erratum

func Use(opener ResourceOpener, input string) error {
	var res Resource
	var err error
	for {
		res, err = opener()
		if err == nil {
			break
		}
		var te TransientError
		if errors.As(err, &te) {
			continue
		}
		return err
	}

	defer res.Close()

	frobErr := func() (e error) {
		defer func() {
			if r := recover(); r != nil {
				if fe, ok := r.(FrobError); ok {
					res.Defrob(fe.defrobTag)
				}
				if err, ok := r.(error); ok {
					e = err
				} else {
					e = fmt.Errorf("panic: %v", r)
				}
			}
		}()
		res.Frob(input)
		return nil
	}()

	return frobErr
}
```

