package erratum

import (
	"errors"
	"fmt"
)

// Use opens a resource via opener, calls Frob(input) on it, and always
// closes the resource exactly once if it was opened successfully.
//
// - If the opener fails with a TransientError, it retries until the
//   resource opens or a non-transient error is returned.
// - If Frob panics with a FrobError, Defrob is called with the
//   FrobError's defrobTag before the resource is closed.
// - Any error (from opening or from a Frob panic) is returned.
func Use(opener ResourceOpener, input string) (err error) {
	var res Resource
	for {
		res, err = opener()
		if err == nil {
			break
		}
		var te TransientError
		if errors.As(err, &te) {
			continue
		}
		return err
	}

	// Close exactly once, no matter what happens after opening.
	// Registered first, so it runs last (after the recover below).
	defer res.Close()

	// Recover from any panic raised by Frob.
	// Registered second, so it runs first: it performs Defrob (for
	// FrobError panics) and converts the panic into the return error
	// before Close runs.
	defer func() {
		r := recover()
		if r == nil {
			return
		}
		if fe, ok := r.(FrobError); ok {
			res.Defrob(fe.defrobTag)
		}
		if e, ok := r.(error); ok {
			err = e
		} else {
			err = fmt.Errorf("panic: %v", r)
		}
	}()

	res.Frob(input)
	return nil
}
